head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");
scwin.gLdMktTp = js_market;
scwin.gIdx_cmb_MBR_ID = 0;
scwin.vScrenID = "ULDSTF30378.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.fn_getListExturePlusMbrId();
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (js_market == "9") {
        rdo_MKT_ID.Enable = true;
        rdo_MKT_ID.ClassName = "TopCondition_Blue";
    } else {
        // 콘트롤 잠그기
        rdo_MKT_ID.Enable = false;
    }
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        //grd_Grid.ColumnProp("SPOT_ISU_TRD_MKT_TP_CD_NM", "Show") = false;
        $c.stf.showObj(panel_mkt, false);
    }
};
scwin.fn_SetHeader = function() {
    //저장용
    scwin.fn_Init_1();
    //삭제용
    scwin.fn_Init_2();
};
scwin.fn_Init_1 = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MBR_EM_CONTACT_INFO_INOUT";

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_info.reset();

	//----W-Craft WebSquare 변환 확인: NameString----//

	//----W-Craft WebSquare 변환 확인: AddRow----//
    dts_info.AddRow(); /*ORG SRC: dts_info.NameString(1, "EXTUREPLUS_MBR_ID") = ""; //안하면 헤더생성안됨*/ X = ""; //안하면 헤더생성안됨

};
scwin.fn_Init_2 = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_del.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MBR_EM_CONTACT_INFO_INOUT";

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_del.reset();

	//----W-Craft WebSquare 변환 확인: NameString----//

	//----W-Craft WebSquare 변환 확인: AddRow----//
    dts_del.AddRow(); /*ORG SRC: dts_del.NameString(1, "EXTUREPLUS_MBR_ID") = ""; //안하면 헤더생성안됨*/ X = ""; //안하면 헤더생성안됨

};
scwin.fn_getListExturePlusMbrId = function() {
    dts_id.DataID = "/NoteMgt.do?method=listExturePlusMbrId&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_id.Reset();
};
scwin.fn_Reload = function() {
    scwin.gIdx_cmb_MBR_ID = cmb_EXTUREPLUS_MBR_ID.Index;
    scwin.fn_SetCode(); //콤보박스 코드 조회 후 내역을 조회하도록 함(이전 선택된 콤보값을 확인하기 위해)

};
scwin.fn_ReloadForPopup = function() {
    cmb_EXTUREPLUS_MBR_ID.Index = scwin.gIdx_cmb_MBR_ID;
    scwin.fn_Search();
    scwin.fn_SetHeader();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/NoteMgt.do?method=listExturePlusMbrInfo";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&EXTUREPLUS_MBR_ID=" + $c.stf.getObjectValue(cmb_EXTUREPLUS_MBR_ID);
    url += "&CHRG_NM=" + $c.stf.getObjectValue(srch_CHRG_NM);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_MASTER.Reset();
};
scwin.fn_SearchDtl = function(row) {
    var url = "/NoteMgt.do?method=readExturePlusMbrInfo";

	//----W-Craft WebSquare 변환 확인: NameString----//
    url += "&NMLIST_SEQ=" + dts_MASTER.NameString(row, "NMLIST_SEQ");
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_info.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_info.Reset();
};
scwin.fn_New = function() {
    scwin.fn_Init_1();
};
scwin.fn_Save = function() {
    /*
    if(getObjectValue(txb_EXTUREPLUS_MBR_NM) == '') {
    	alert("[회원사명]을 입력하세요." );

	//----W-Craft WebSquare 변환 확인: focus----//
    	txb_EXTUREPLUS_MBR_NM.focus();
    	return;
    }
    if(getObjectValue(txb_DEP_NM) == '') {
    	alert("[소속부서]를 입력하세요." );

	//----W-Craft WebSquare 변환 확인: focus----//
    	txb_DEP_NM.focus();
    	return;
    }
    if(getObjectValue(txb_TEL_NO) == '') {
    	alert("[전화번호(회사)]를 입력하세요." );

	//----W-Craft WebSquare 변환 확인: focus----//
    	txb_TEL_NO.focus();
    	return;
    }
    if(getObjectValue(txb_JOBTITL_NM) == '') {
    	alert("[직급]을 입력하세요." );

	//----W-Craft WebSquare 변환 확인: focus----//
    	txb_JOBTITL_NM.focus();
    	return;
    }
    */
    if ($c.stf.getObjectValue(txb_CHRG_NM) == '') {
        alert("[성명]을 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_CHRG_NM.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_CELLPHONE_NO) == '') {
        alert("[휴대전화번호]를 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_CELLPHONE_NO.focus();
        return;
    }
    var regExpTel = /^0(?:\d{1}|\d{2})-(?:\d{3}|\d{4})-\d{4}$/; //정규식 체크 - 전화번호
    var regExpCell = /^01(?:0|1|[6-9])-(?:\d{4})-\d{4}$/; //정규식 체크 - 휴대폰번호

    if (!regExpTel.test($c.stf.getObjectValue(txb_TEL_NO)) && $c.stf.getObjectValue(txb_TEL_NO) != '') {
        alert("[전화번호(회사)]를 확인해 주세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_TEL_NO.focus();
        return;
    }
    if (!regExpCell.test($c.stf.getObjectValue(txb_CELLPHONE_NO))) {
        alert("[휴대전화번호]를 확인해 주세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_CELLPHONE_NO.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        gLastJob = "저장"; /*ORG SRC: dts_info.NameValue(1, "EMP_NO") = js_emp_no;*/ X = js_emp_no; /*ORG SRC: dts_info.NameValue(1, "LD_MKT_TP_CD") = js_market;*/ X = js_market;
        trs_Save.Action = "/NoteMgt.do?method=registerExturePlusMbrInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_info)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_Save.Post();
    }
};
$c.lce.fn_checkPhoneNumber = function(obj) {
    var text = $c.stf.getObjectValue(obj).replace(/-/g, "");
    var regExpTel = /(^02.{0}|^01.{1}|[0-9]{3})([0-9]+)([0-9]{4})/; //정규식 체크 - 전화번호

    $c.stf.setObjectValue(obj, text.replace(regExpTel, "$1-$2-$3"));
};
scwin.fn_Delete = function(row) {
    if (confirm('삭제 하시겠습니까?')) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
        gLastJob = "삭제"; /*ORG SRC: dts_del.NameString(1, "NMLIST_SEQ") = dts_MASTER.NameString(row, "NMLIST_SEQ");*/ X = dts_MASTER.NameString(row, "NMLIST_SEQ"); /*ORG SRC: dts_del.NameString(1, "EMP_NO") = js_emp_no;*/ X = js_emp_no;
        trs_Save.Action = "/NoteMgt.do?method=deleteExturePlusMbrInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_del)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_Save.Post();
    }
};
scwin.btn_Search_onclick = function(e) {
    scwin.fn_Reload();
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {

	//----W-Craft WebSquare 변환 확인: ClearData----//
        dts_MASTER.ClearData();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_id_OnLoadError = function() {
    $c.stf.alert_error(dts_info);
};
scwin.dts_id_OnLoadCompleted = function(rowcount) {
    cmb_EXTUREPLUS_MBR_ID.Index = scwin.gIdx_cmb_MBR_ID;
    scwin.fn_Search();
    scwin.fn_SetHeader();
};
scwin.trs_Save_OnFail = function() {

	//----W-Craft WebSquare 변환 확인: alert_error2----//
    alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    alert(msg);
    scwin.fn_Reload();
};
scwin.btn_Upload_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30379.gfm", "엑셀 업로드", 200, 100, 100, 100, "window");
};
scwin.btn_Excel_onclick = function(e) {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var file_name = "회원사 비상연락망 명부";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xls";

	//----W-Craft WebSquare 변환 확인: GridToOffice----//
    grd_Grid.GridToOffice(file_name, xls_path, "8", 0);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    scwin.fn_SearchDtl(row);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == "DEL_YN") {
        scwin.fn_Delete(row);
    }
};
scwin.btn_Init_onclick = function(e) {
    scwin.fn_New();
};
scwin.btn_Save_onclick = function(e) {
    scwin.fn_Save();
};
scwin.txb_TEL_NO_onchange = function() {
    scwin.fn_CheckPhoneNumber(txb_TEL_NO);
};
scwin.txb_CELLPHONE_NO_onchange = function() {
    scwin.fn_CheckPhoneNumber(txb_CELLPHONE_NO);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.libRoundPanel.PanelToGroupBox(panel_2);
    scwin.fn_Init();
    scwin.fn_SetCode();
    scwin.fn_SetHeader();

    //fn_Search();

};
